def _page(title, description, intro, sections, related=(), external_links=()):
    return {
        "title": title, "description": description, "intro": intro,
        "sections": sections, "related": list(related),
        "external_links": list(external_links),
    }


def _affiliate_link(before, link_text, url, after=""):
    return {
        "before": before,
        "link_text": link_text,
        "url": url,
        "after": after,
        "sponsored": True,
    }


