DOC_ORDER = [slug for _group, slugs in DOC_GROUPS for slug in slugs]


def _searchable_paragraph_text(paragraph):
    if isinstance(paragraph, dict):
        return " ".join(
            str(paragraph.get(key, "")).strip()
            for key in ("before", "link_text", "after")
            if paragraph.get(key)
        )
    return str(paragraph).strip()


def _documentation_search_index():
    """Build a browser-searchable index from the same content rendered by the docs."""
    group_by_slug = {
        slug: group
        for group, slugs in DOC_GROUPS
        for slug in slugs
    }
    index = []
    for slug in DOC_ORDER:
        page = DOCS[slug]
        overview = " ".join((page["description"], page["intro"]))
        index.append({
            "title": page["title"],
            "section": "Overview",
            "group": group_by_slug.get(slug, "Documentation"),
            "text": overview,
            "url": f"/docs/{slug}",
        })
        for section_number, (heading, paragraphs) in enumerate(page["sections"], start=1):
            index.append({
                "title": page["title"],
                "section": heading,
                "group": group_by_slug.get(slug, "Documentation"),
                "text": " ".join(_searchable_paragraph_text(item) for item in paragraphs),
                "url": f"/docs/{slug}#section-{section_number}",
            })
        if page.get("controls"):
            control_text = " ".join(
                " ".join((
                    str(control.get("label", "")),
                    str(control.get("effect", "")),
                    str(control.get("analogy", "")),
                ))
                for control in page["controls"]
            )
            index.append({
                "title": page["title"],
                "section": "Control reference",
                "group": group_by_slug.get(slug, "Documentation"),
                "text": control_text,
                "url": f"/docs/{slug}#control-reference",
            })
    return index


@routes.route("/docs")
def docs_index():
    return render_template("docs.html", page=None, pages=DOCS, groups=DOC_GROUPS,
                           canonical=_canonical("/docs"), previous_page=None, next_page=None,
                           docs_search_index=_documentation_search_index())


@routes.route("/docs/<slug>")
def docs_page(slug):
    page = DOCS.get(slug)
    if not page:
        return render_template("docs.html", page=None, pages=DOCS, groups=DOC_GROUPS,
                               canonical=_canonical("/docs"), previous_page=None, next_page=None,
                               docs_search_index=_documentation_search_index()), 404
    page_index = DOC_ORDER.index(slug)
    previous_slug = DOC_ORDER[page_index - 1] if page_index else None
    next_slug = DOC_ORDER[page_index + 1] if page_index + 1 < len(DOC_ORDER) else None
    return render_template("docs.html", page=page, slug=slug, pages=DOCS, groups=DOC_GROUPS,
                           canonical=_canonical(f"/docs/{slug}"),
                           previous_page=(previous_slug, DOCS[previous_slug]) if previous_slug else None,
                           next_page=(next_slug, DOCS[next_slug]) if next_slug else None)


@routes.route("/docs/blank-palette-library/download", methods=["POST"])
def blank_palette_library_download():
    material_name = str(request.form.get("material_name", "")).strip()
    try:
        library = build_blank_palette_library(material_name)
    except ValueError as error:
        return Response(str(error), status=400, mimetype="text/plain")
    filename_material = secure_filename(material_name) or "material"
    return send_file(
        library,
        mimetype="application/xml",
        as_attachment=True,
        download_name=f"{filename_material}-blank-rasterizer-palette.clb",
    )


def _canonical(path):
    base = current_app.config.get("PUBLIC_APP_URL") or request.url_root.rstrip("/")
    return f"{base}{path}"


@routes.route("/sitemap.xml")
def sitemap():
    paths = ["/", "/laser-engraving-tool", "/color-laser-engraving-tool", "/depthmap-relief-engraving-tool", "/founding-sponsors", "/experimental-laboratories", "/holographic-etching", "/depthmap-generator", "/color-discovery", "/material-libraries", "/community-set", "/docs"]
    paths.extend(f"/docs/{slug}" for slug in DOCS)
    body = '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'
    body += "\n".join(f"  <url><loc>{_canonical(path)}</loc></url>" for path in paths)
    body += "\n</urlset>\n"
    return Response(body, mimetype="application/xml")


@routes.route("/robots.txt")
def robots():
    return Response(f"User-agent: *\nAllow: /\nSitemap: {_canonical('/sitemap.xml')}\n",
                    mimetype="text/plain")
